/**
 * The browser PUT bench's worker: seal generated bytes into OPFS (`seal`),
 * then PUT the stored File through the upload track's client (`put`), as
 * the upload track sends it; `clean` removes the scratch directory.
 */
import { createOpfsBlobStore } from '../../src/hosts/browser/objects.js';
import { createLfsClient } from '../../src/wire/client.js';

const CHUNK = 1024 * 1024;
let scratch: FileSystemDirectoryHandle | null = null;
let sealed: { oid: string; size: number } | null = null;

function generated(size: number, salt: number) {
	const seed = Uint8Array.from(
		{ length: CHUNK },
		(_, i) => (i * 2_654_435_761) >>> 24,
	);
	let at = 0;
	return new ReadableStream<Uint8Array>({
		pull(controller) {
			if (at >= size) return controller.close();
			const chunk = seed.slice(0, Math.min(CHUNK, size - at));
			chunk[0] = at & 0xff;
			chunk[1] = (at >> 8) & 0xff;
			chunk[2] = salt;
			controller.enqueue(chunk);
			at += chunk.byteLength;
		},
	});
}

addEventListener(
	'message',
	async ({
		data,
	}: MessageEvent<{
		step: 'seal' | 'put' | 'clean';
		size?: number;
		salt?: number;
		url?: string;
	}>) => {
		try {
			const root = await navigator.storage.getDirectory();
			if (data.step === 'seal') {
				scratch = await root.getDirectoryHandle(
					`bench-put-${crypto.randomUUID()}`,
					{ create: true },
				);
				const result = await createOpfsBlobStore(scratch).seal(
					generated(data.size ?? 0, data.salt ?? 0),
				);
				if (result.error !== null) throw new Error(result.error.message);
				sealed = result.data;
				return postMessage({ ok: sealed });
			}
			if (data.step === 'put') {
				if (scratch === null || sealed === null)
					throw new Error('nothing sealed');
				const file = await createOpfsBlobStore(scratch).read(sealed.oid);
				if (file === null) throw new Error('the sealed file is gone');
				const lfs = createLfsClient({
					url: data.url ?? '',
					headers: { authorization: 'Bearer alice' },
				});
				const started = performance.now();
				const asked = await lfs.batch('upload', [sealed]);
				if (asked.error !== null) throw new Error(asked.error.message);
				const action = asked.data[0]?.actions?.upload;
				if (action === undefined) throw new Error('no upload action');
				const put = await lfs.put(action, file);
				if (put.error !== null) throw new Error(put.error.message);
				return postMessage({ ok: { ms: performance.now() - started } });
			}
			if (scratch !== null)
				await root.removeEntry(scratch.name, { recursive: true });
			postMessage({ ok: true });
		} catch (cause) {
			postMessage({ error: String(cause) });
		}
	},
);
